-- =============================================================================
-- Loan charges as per Loan Dhoran 2026-27 (board meeting 05, 05/06/2026)
--
-- Updates the 15 Loan Charges schemes: loan form fees, LPC, shares, stamp duty,
-- valuation, search report, CERSAI, legal / advocate fees.
--
-- HOW TO RUN: Supabase dashboard -> SQL Editor -> New query -> paste this whole
--   file -> click in the editor, press Ctrl+A (nothing else highlighted) -> Run.
--   The last line of the file is: -- END OF FILE
--   * Each scheme is matched by its code (1602, 1603, ...). Its lines are replaced
--     with the 2026-27 lines below; name, order and active flag stay as they are.
--   * Every change is written to loan_scheme_audit with the old lines, so any
--     scheme can be restored from there.
--   * Written for tables where loan_scheme_fields links to loan_schemes by scheme_code.
--   * Runs in one transaction: if anything fails, nothing is changed.
--   * Safe to run again (re-applies the same values).
-- After running: open Loan Charges and press Refresh.
-- =============================================================================

begin;

create temp table charges_2026_27 (scheme_code text, name text, sort_order integer, fields jsonb) on commit drop;

insert into charges_2026_27 (scheme_code, name, sort_order, fields) values
